catalogue_order_page = page("Catalogue order request","ORDER REQUEST","Send a request for this selected catalogue item. FORME will confirm the final details before dispatch.",catalogue_order_body,canonical="https://sobujkhamarofficial-ctrl.github.io/fashionstore/pages/catalogue-order.html")
